const config = {
    "previewFeatures": [],
    "clientVersion": "7.10.0",
    "engineVersion": "0edf323efd1d98336f3f0a68684b56f689b900d3",
    "activeProvider": "postgresql",
    "inlineSchema": "// Rental & Property Management — database schema (MVP: Sprints 1–5)\n//\n// The core idea: we never store \"how much a tenant owes.\" We store\n// CHARGES (what they owe) and PAYMENTS (what came in), and a small\n// join table saying which payment paid off which charge. The balance\n// for any tenant, any month, any type (rent/water/deposit) is always\n// worked out from those three tables — never stored and never stale.\n\ngenerator client {\n  provider     = \"prisma-client\"\n  output       = \"../generated/prisma\"\n  moduleFormat = \"cjs\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ─────────────────────────────────────────────────────────────\n// People who log in (owner + staff). Tenants are NOT users —\n// they never log in, so they live in their own table below.\n// ─────────────────────────────────────────────────────────────\n\nenum Role {\n  OWNER\n  STAFF\n  ADMIN\n}\n\nmodel User {\n  id       String  @id @default(cuid())\n  kindeId  String  @unique // the \"sub\" claim from the Kinde JWT\n  email    String  @unique\n  name     String?\n  role     Role    @default(OWNER)\n  isActive Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // one owner can hold one property today; the array just means we're\n  // not blocked if a second property/owner is added later.\n  properties       Property[]\n  chargesCreated   Charge[]   @relation(\"ChargeCreatedBy\")\n  paymentsRecorded Payment[]  @relation(\"PaymentRecordedBy\")\n}\n\n// ─────────────────────────────────────────────────────────────\n// The apartment block itself, and its default settings.\n// ─────────────────────────────────────────────────────────────\n\nmodel Property {\n  id      String @id @default(cuid())\n  ownerId String\n  owner   User   @relation(fields: [ownerId], references: [id])\n\n  name             String  @unique\n  address          String\n  location         String?\n  description      String?\n  defaultWaterRate Decimal @default(0) // KSh per unit, used when generating a new water bill\n  currency         String  @default(\"KES\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  houses House[]\n}\n\n// ─────────────────────────────────────────────────────────────\n// Individual rental units.\n// ─────────────────────────────────────────────────────────────\n\nenum HouseStatus {\n  VACANT\n  OCCUPIED\n  RESERVED\n  NOTICE_GIVEN\n  MAINTENANCE\n  INACTIVE\n}\n\nmodel House {\n  id         String   @id @default(cuid())\n  propertyId String\n  property   Property @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n\n  unitNumber       String // \"H01\"\n  houseType        String? // \"Bedsitter\", \"1BR\" etc — free text for now\n  waterMeterNumber String?\n\n  // These are only the ADVERTISED figures for whoever moves in next.\n  // Neither is ever read to work out an existing tenant's rent or\n  // deposit — those are frozen on the Tenancy the moment they move in.\n  defaultMonthlyRent   Decimal\n  defaultDepositAmount Decimal? // falls back to defaultMonthlyRent if left unset\n\n  status HouseStatus @default(VACANT)\n  notes  String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  tenancies Tenancy[]\n\n  @@unique([propertyId, unitNumber])\n}\n\n// ─────────────────────────────────────────────────────────────\n// The people who rent the houses. Never log in, never a User.\n// ─────────────────────────────────────────────────────────────\n\nenum TenantStatus {\n  ACTIVE\n  FORMER\n}\n\nmodel Tenant {\n  id String @id @default(cuid())\n\n  fullName              String\n  phone                 String\n  altPhone              String?\n  nationalId            String?\n  email                 String?\n  occupation            String?\n  emergencyContactName  String?\n  emergencyContactPhone String?\n\n  status TenantStatus @default(ACTIVE)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  tenancies Tenancy[]\n}\n\n// ─────────────────────────────────────────────────────────────\n// One stay by one tenant in one house. This is the record that\n// \"freezes\" the rent and deposit so later rent changes never\n// touch history. A house's story over time is its list of\n// Tenancies, oldest to newest.\n// ─────────────────────────────────────────────────────────────\n\nenum TenancyStatus {\n  ACTIVE\n  NOTICE_GIVEN\n  VACATED\n}\n\nmodel Tenancy {\n  id String @id @default(cuid())\n\n  houseId  String\n  house    House  @relation(fields: [houseId], references: [id])\n  tenantId String\n  tenant   Tenant @relation(fields: [tenantId], references: [id])\n\n  // Copied in at move-in and then left alone. If the owner ever\n  // needs to change rent mid-tenancy, that's a deliberate edit here\n  // — it only affects rent charges generated AFTER the change,\n  // because past charges already have their own amount saved.\n  monthlyRent     Decimal\n  depositRequired Decimal // defaults to monthlyRent in the API, but can be set to an agreed figure\n\n  startDate           DateTime\n  expectedEndDate     DateTime?\n  // Captured once, at move-in — the starting point for water billing once\n  // Sprint 6 builds proper meter-reading history. Not billed against here.\n  openingWaterReading Decimal?\n  notes               String?\n  noticeDate          DateTime?\n  moveOutReason       String?\n  actualEndDate       DateTime?\n\n  status TenancyStatus @default(ACTIVE)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  charges       Charge[]\n  payments      Payment[]\n  depositRefund DepositRefund?\n  // NOTE: \"only one ACTIVE tenancy per house\" is enforced in application\n  // code today. A follow-up migration should add a partial unique index\n  // (Postgres: UNIQUE (houseId) WHERE status = 'ACTIVE') as a hard safety net.\n\n  @@index([houseId, status])\n}\n\n// ─────────────────────────────────────────────────────────────\n// Something a tenant owes: a month's rent, a water bill, the\n// deposit, or a one-off charge. This is the \"expected\" side.\n// ─────────────────────────────────────────────────────────────\n\nenum ChargeType {\n  RENT\n  WATER\n  RENTDEPOSIT\n  WATERDEPOSIT\n  TRASH\n  TRASHDEPOSIT\n  SECURITYDEPOSIT\n  SECURITY\n  SERVICEFEE\n  OTHER\n}\n\nmodel Charge {\n  id String @id @default(cuid())\n\n  tenancyId String\n  tenancy   Tenancy @relation(fields: [tenancyId], references: [id])\n\n  type ChargeType\n\n  // First day of the month this charge is for (e.g. RENT for August).\n  // Left empty for one-off OTHER charges. This field is what lets us\n  // answer \"what does this tenant owe for August\" without a separate table.\n  periodMonth DateTime?\n\n  amount      Decimal\n  description String?\n  dueDate     DateTime?\n\n  // Charges are never deleted — a mistaken charge is voided with a reason\n  // and stays visible, so the history is never silently rewritten.\n  voidedAt   DateTime?\n  voidReason String?\n\n  createdById String\n  createdBy   User     @relation(\"ChargeCreatedBy\", fields: [createdById], references: [id])\n  createdAt   DateTime @default(now())\n\n  allocations PaymentAllocation[]\n\n  // Stops the same month's rent (or water bill) being generated twice.\n  // NULL periodMonth (OTHER charges) is exempt — Postgres treats NULLs\n  // as distinct, so one-off charges are never blocked by this.\n  @@unique([tenancyId, type, periodMonth])\n  @@index([tenancyId, periodMonth])\n}\n\n// ─────────────────────────────────────────────────────────────\n// Money that actually came in. This is the \"actual\" side.\n// ─────────────────────────────────────────────────────────────\n\nenum PaymentMethod {\n  MPESA\n  BANK\n  CASH\n  OTHER\n}\n\n// How the payment reached the system. Everything today is MANUAL —\n// the owner typing it in. The other values don't get used yet, but\n// having the field means an M-Pesa/bank integration later just writes\n// into this same table instead of needing a new one.\nenum PaymentSource {\n  MANUAL\n  MPESA_AUTO\n  BANK_AUTO\n}\n\nmodel Payment {\n  id String @id @default(cuid())\n\n  tenancyId String\n  tenancy   Tenancy @relation(fields: [tenancyId], references: [id])\n\n  amount Decimal\n  paidAt DateTime\n\n  // No \"type\" here on purpose: a single payment (one lump of cash/M-Pesa)\n  // can settle a mix of deposit, rent and a utility bill in one go. What\n  // it actually paid for is entirely described by its PaymentAllocation\n  // rows — each pointing at one Charge, which has its own type. See the\n  // allocation cascade below.\n\n  method    PaymentMethod\n  source    PaymentSource @default(MANUAL)\n  reference String? // e.g. M-Pesa code — checked for duplicates in the service layer\n  notes     String?\n\n  recordedById String\n  recordedBy   User   @relation(\"PaymentRecordedBy\", fields: [recordedById], references: [id])\n\n  // Reversed, never deleted, so the trail always shows what happened.\n  voidedAt   DateTime?\n  voidReason String?\n\n  createdAt DateTime @default(now())\n\n  allocations PaymentAllocation[]\n  attachments Attachment[]\n\n  @@index([tenancyId])\n  @@index([reference])\n}\n\n// ─────────────────────────────────────────────────────────────\n// The link: how much of this payment went to that charge.\n// A payment can be split across several charges — even charges of\n// different types (e.g. one payment finishes off the deposit, then\n// clears July's rent, then puts a dent in August's rent).\n// A charge can be paid off by several payments over time.\n//\n// AUTO-ALLOCATION ORDER (service layer, not the database):\n// when money isn't manually pointed at specific charges, it is applied\n// to a tenancy's outstanding charges in this order, oldest first within\n// each group, until the money runs out:\n//   1. DEPOSIT   (always settled first — the owner's explicit rule)\n//   2. RENT      (oldest unpaid month first; a 3-month prepayment\n//                 walks forward through however many month charges exist)\n//   3. WATER     (oldest unpaid bill first)\n//   4. OTHER     (oldest due date first — trash, etc.)\n// Any amount left over once every outstanding charge is cleared is\n// simply unallocated credit (payment.amount − sum of its allocations).\n// It isn't parked in a new table — the same allocation routine runs\n// again, against this tenancy's leftover credit, every time a NEW\n// charge is created (next month's rent job, a fresh water bill, an\n// ad-hoc trash charge), so a prepayment quietly catches up automatically.\n// ─────────────────────────────────────────────────────────────\n\nmodel PaymentAllocation {\n  id String @id @default(cuid())\n\n  paymentId String\n  payment   Payment @relation(fields: [paymentId], references: [id])\n  chargeId  String\n  charge    Charge  @relation(fields: [chargeId], references: [id])\n\n  amount    Decimal\n  createdAt DateTime @default(now())\n\n  @@unique([paymentId, chargeId])\n}\n\n// ─────────────────────────────────────────────────────────────\n// Proof of payment — the M-Pesa screenshot or bank slip.\n// ─────────────────────────────────────────────────────────────\n\nmodel Attachment {\n  id String @id @default(cuid())\n\n  paymentId String\n  payment   Payment @relation(fields: [paymentId], references: [id])\n\n  url          String // Cloudinary URL\n  mimeType     String\n  sizeBytes    Int?\n  uploadedById String\n\n  createdAt DateTime @default(now())\n}\n\n// ─────────────────────────────────────────────────────────────\n// Move-out: what happened to the deposit. Kept separate from\n// Charge/Payment because it's a one-time settlement, not an\n// ongoing balance.\n// ─────────────────────────────────────────────────────────────\n\nmodel DepositRefund {\n  id String @id @default(cuid())\n\n  tenancyId String  @unique\n  tenancy   Tenancy @relation(fields: [tenancyId], references: [id])\n\n  depositHeld  Decimal // what was actually paid in, from the Charge/Payment records\n  refundAmount Decimal\n  refundDate   DateTime?\n  method       PaymentMethod?\n  notes        String?\n\n  createdAt DateTime @default(now())\n\n  deductions DepositDeduction[]\n}\n\nmodel DepositDeduction {\n  id String @id @default(cuid())\n\n  refundId String\n  refund   DepositRefund @relation(fields: [refundId], references: [id])\n\n  reason String\n  amount Decimal\n}\n",
    "runtimeDataModel": {
        "models": {},
        "enums": {},
        "types": {}
    },
    "parameterizationSchema": {
        "strings": [],
        "graph": ""
    }
};
